import {createSettingsSaver} from './settings-save.mjs';
import {createWorkspaceUI} from './workspace-ui.mjs';
import {createJobListUI} from './job-list-ui.mjs';
import {createGreetingUI} from './greeting-ui.mjs';
import {createBrowserDiagnosticsAction,browserDiagnosticsInstructions} from './browser-diagnostics-ui.mjs';
import {createAIProviderUI,chatgptUsageUrl} from './ai-provider-ui.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={ghost:'M5 20V9a7 7 0 0 1 14 0v11l-3-2-4 2-4-2-3 2ZM9 9v2m6-2v2',dashboard:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',briefcase:'M4 7h16v14H4zM8 7V3h8v4M9 7v14m6-14v14',send:'m3 11 18-8-8 18-2-8-8-2Zm8 2 10-10',copy:'M8 8h12v13H8zM16 8V3H3v13h5',skip:'m5 4 11 8-11 8V4Zm14 0v16',message:'M21 11a9 9 0 0 1-9 9H4l-2 2v-11a9 9 0 0 1 19 0ZM7 10h10m-10 4h6',reply:'m9 5-6 6 6 6m-6-6h11a7 7 0 0 1 7 7',inbox:'M5 4h14l3 12v4H2v-4L5 4Zm-3 12h6l2 3h4l2-3h6',chart:'M4 3v18h18M8 15l4-5 4 2 5-7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm-2-6h4l1 3 3 1 3 2-1 3v3l1 3-3 2-3 1-1 2h-4l-1-2-3-1-3-2 1-3v-3L3 8l3-2 3-1 1-3Z',calendar:'M4 5h16v16H4zM8 2v6m8-6v6M4 11h16',pin:'M19 9c0 6-7 12-7 12S5 15 5 9a7 7 0 0 1 14 0ZM12 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 7v6m0-10v1',check:'m5 12 4 4L19 6',warn:'m12 3 10 18H2L12 3Zm0 6v5m0 3v1',trash:'M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7m4-7v7',play:'m7 3 14 9-14 9V3Z',stop:'M5 5h14v14H5z',globe:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM3 12h18M12 3c-5 6-5 12 0 18m0-18c5 6 5 12 0 18',download:'M12 3v12m-5-5 5 5 5-5M3 15v6h18v-6',upload:'M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6',plus:'M12 4v16M4 12h16',close:'m6 6 12 12M6 18 18 6',file:'M5 3h10l5 5v13H5V3Zm10 0v6h5M8 13h8m-8 4h6',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z',key:'M8 3a5 5 0 1 0 0 10 5 5 0 0 0 0-10Zm3 9 9 9m-5-5 3-3m0 6 3-3',refresh:'M20 7a8 8 0 1 0 0 10M20 3v5h-5',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v5l4 3',print:'M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6z'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.info}"/></svg>`;
const btn=(text,action,style='',i='',attrs='')=>`<button class="btn ${style}" data-action="${action}" ${attrs}>${i?icon(i):''}${text}</button>`;
const pill=(text,color='')=>`<span class="pill ${color}">${esc(text)}</span>`;
const color=s=>({'合适':'green','已沟通':'blue','不合适':'red','待确认':'orange','待核实':'orange','有面试':'purple','草稿':'blue','已发送':'green','收到':''}[s]||'');
let state,jobs=[],messages=[],reports=[],page='dashboard',settingsTab='search',jobFilter='全部',query='',selected=new Set(),contact='',toastTimer,confirmResolver=null,modalHandler=null;
async function api(url,body){const r=await fetch('/api/'+url,{...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Local-App':'ghost-job'},body:JSON.stringify(body)})});const d=await r.json();if(!r.ok)throw Error(d.error||'操作失败');return d;}
function toast(text,error=false){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').className='show'+(error?' error':'');toastTimer=setTimeout(()=>$('#toast').className='',6500);}
function empty(title,desc,i='inbox',action=''){return `<div class="empty"><div class="empty-icon">${icon(i)}</div><h3>${title}</h3><p>${desc}</p>${action}</div>`;}
function date(t){return new Date(t).toLocaleString('zh-CN',{hour12:false});}
function heading(title,desc,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div>${actions||`<div class="today">${icon('calendar')}${new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date())}</div>`}</div>`;}
function modal(title,content,footer=''){modalHandler=null;$('#modal-content').innerHTML=`<div class="modal-header"><h2>${title}</h2><button class="text-btn" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${content}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){if(confirmResolver){confirmResolver(false);confirmResolver=null;}$('#modal').close();modalHandler=null;}
function confirmAction(title,description,label='确认'){return new Promise(resolve=>{modal(title,`<p class="panel-desc">${esc(description)}</p>`,btn('取消','close-modal')+btn(label,'confirm','primary'));confirmResolver=resolve;});}
$('#modal').addEventListener('cancel',()=>{if(confirmResolver)confirmResolver(false);confirmResolver=null;});
function download(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function refresh(render=true,skipUnchanged=false){
 const next=await api('state');
 const unchanged=skipUnchanged&&state&&JSON.stringify(state)===JSON.stringify(next);
 state=next;aiProviderUI.observeState(next.chatgpt);if(render&&!unchanged)draw();updateWorkspaceStatus();
 $('#footer-status').textContent=state.browser.connected?'求职浏览器已连接 · 数据保存在本机':'数据保存在本机 · 求职浏览器未连接';
}
const navs=[['dashboard','工作台','dashboard'],['analytics','求职分析','chart'],['jobs','岗位管理','briefcase'],['messages','消息','message'],['settings','配置中心','settings']];
function nav(){ $('#nav').innerHTML=navs.map(([id,title,i])=>{const count=id==='jobs'?state?.stats.jobs:id==='messages'?state?.conversations.length:null;return `<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''} title="${title}" aria-label="${title}">${icon(i)}<span class="nav-label">${title}</span>${count?`<small class="nav-count" aria-hidden="true">${count}</small>`:''}</a>`;}).join(''); }
function statsCards(){const s=state.stats,t=state.task;return `<div class="stats">${[['briefcase',s.sent,'累计投递','已确认沟通的岗位'],['send',t.sent,'本次投递','本轮成功沟通'],['copy',t.duplicates,'本次重复','已记录的岗位'],['skip',t.skipped,'本次跳过','未达到筛选条件'],['message',s.replied,'自动回复','已确认自动发送的消息'],['reply',s.review,'待确认岗位','基础筛选通过'],['inbox',s.received,'收到消息','已同步的对话消息']].map(([i,n,title,desc])=>`<div class="stat"><div class="stat-icon">${icon(i)}</div><strong>${n}</strong><b>${title}</b><small>${desc}</small></div>`).join('')}</div>`;}
function dashboard(){const s=state.settings,t=state.task;return heading('工作台','把重复的工作交给工具，把时间留给更好的机会。')+statsCards()+`<div class="dashboard-grid"><section class="panel assistant-panel"><div class="panel-body"><div class="assistant-heading"><h2>求职助手</h2>${pill(s.autoSend?'自动沟通模式':'筛选与确认模式',s.autoSend?'orange':'blue')}</div><p class="panel-desc">按照你的求职方向筛选岗位，结合简历分析匹配度。<br>每一份值得沟通的机会，都在这里有迹可循。</p><div class="preferences"><div>${icon('search')}<label>岗位关键词</label><strong>${esc(s.keywords||'尚未设置')}</strong><button class="text-btn" data-action="go-settings">编辑 ${icon('external')}</button></div><div>${icon('pin')}<label>目标城市</label><strong>${esc(s.cities||'尚未设置')}</strong></div></div><div class="run-state"><div><span>岗位任务</span>${pill(t.phase,t.running?'green':'')}</div><div><span>自动回复</span>${pill(state.replyTask.phase||(state.autoReply?'运行中':'未开启'),state.autoReply?'green':'')}</div><p>${state.browser.connected?'求职浏览器已连接，可读取当前页面或开始筛选。':'首次使用先打开求职浏览器，手动登录 BOSS 直聘。'}</p></div><div class="notice">已读取 <strong>${state.stats.jobs}</strong> 个岗位 · <button class="text-btn" data-action="go-jobs">查看岗位管理</button></div>${btn('读取当前页岗位','collect','wide primary','download',t.busy?'disabled':'')}${btn(t.running?'停止任务':s.autoSend?'开始自动筛选与沟通':'开始自动筛选',t.running?'stop-task':'start-task',t.running?'wide danger':'wide soft',t.running?'stop':'play')}${btn(state.replyTask.busy&&!state.autoReply?'正在停止…':state.autoReply?'停止自动回复':'开启当前会话自动回复',state.autoReply?'stop-reply':'start-reply','wide '+(state.autoReply?'danger':'soft'),'reply')}<div style="display:flex;gap:9px;margin-top:9px">${btn('打开求职浏览器','open-browser','outline','globe','style="flex:1"')}${btn('查看岗位（'+state.stats.jobs+'）','go-jobs','','briefcase','style="flex:1"')}</div></div></section><section class="panel logs-panel"><div class="panel-title"><h2>运行日志</h2><small>共 ${state.logs.length} 条</small><button class="text-btn right" data-action="clear-logs">${icon('trash')}清空</button></div><div class="logs">${state.logs.length?state.logs.map(l=>`<div class="log ${esc(l.level)}"><time>${new Date(l.time).toLocaleTimeString('zh-CN',{hour12:false})}</time>${icon(l.level==='success'?'check':l.level==='warn'||l.level==='error'?'warn':'info')}<span>${esc(l.text)}</span></div>`).join(''):empty('等待新的进展','配置求职方向并开始任务后，运行过程会显示在这里。','clock')}</div></section></div><div class="setup-note">${icon('info')}<span>${s.resume?'简历已配置。AI 筛选 '+(s.aiEnabled?'已开启':'未开启')+'，今日已处理 '+state.stats.today+' / '+s.dailyLimit+' 次沟通。':'还差一步：配置求职方向、AI 服务和简历，让岗位筛选更适合你。'}</span><button data-action="go-settings">前往配置中心 →</button></div>`;}
function jobRows(){const filtered=jobs.filter(j=>(jobFilter==='全部'||j.status===jobFilter)&&[j.title,j.company,j.city,j.description].join(' ').toLowerCase().includes(query.toLowerCase()));if(!filtered.length)return empty(jobs.length?'没有符合条件的岗位':'从第一份机会开始',jobs.length?'试试其他关键词或筛选条件。':'打开求职浏览器读取岗位，或先添加岗位、导入 JSON，体验本地管理。','briefcase',btn('添加岗位','add-job','primary','plus')+' '+btn('载入示例','demo','','spark'));return `<div class="table-wrap"><table><thead><tr><th><input type="checkbox" id="select-all" aria-label="选择所有筛选结果"></th><th>岗位 / 公司</th><th>薪资 / 城市</th><th>匹配度</th><th>判断结果</th><th>沟通状态</th><th>操作</th></tr></thead><tbody>${filtered.map(j=>`<tr><td><input type="checkbox" data-select="${esc(j.id)}" ${selected.has(j.id)?'checked':''} aria-label="选择 ${esc(j.title)}"></td><td><button class="job-title text-btn" data-action="job-detail" data-id="${esc(j.id)}">${esc(j.title)}</button><span class="sub">${esc(j.company||'未填写公司')} ${j.demo?pill('示例'):''}</span></td><td><span class="salary">${esc(j.salary||'面议')}</span><span class="sub">${esc(j.city||'未填写')}</span></td><td><div class="score">${j.score===null||j.score===undefined?'—':esc(j.score)}${j.score!=null?`<i><b style="width:${Math.min(100,Math.max(0,Number(j.score)||0))}%"></b></i>`:''}</div></td><td>${pill(j.status,color(j.status))}</td><td>${pill(j.stage||'未标记',color(j.stage))}</td><td><div class="actions"><button class="text-btn" data-action="analyze-one" data-id="${esc(j.id)}">AI 分析</button><button class="text-btn" data-action="job-detail" data-id="${esc(j.id)}">详情</button></div></td></tr>`).join('')}</tbody></table></div>`;}
function jobsPage(){return heading('岗位管理',`共 ${jobs.length} 个岗位 · 把每个机会整理清楚，再做决定。`,`<div class="inline-actions">${btn('导入','import','','upload')}${btn('导出','export','','download')}${btn('添加岗位','add-job','primary','plus')}</div>`)+`<div class="toolbar"><div class="search">${icon('search')}<input id="job-search" placeholder="搜索岗位、公司或城市" value="${esc(query)}" aria-label="搜索岗位"></div><div class="filter-tabs">${['全部','待分析','合适','不合适','待确认','已沟通'].map(f=>`<button class="${jobFilter===f?'active':''}" data-action="filter" data-filter="${f}">${f}</button>`).join('')}</div><span class="spacer"></span>${btn('批量分析','analyze-selected','soft','spark')}${btn('删除','delete-selected','','trash')}</div><section class="panel" id="job-table">${jobRows()}</section><div class="setup-note">${icon('globe')}<span>岗位来自你的浏览器读取或手动导入；示例岗位不参与真实投递。</span><button data-action="collect">读取当前浏览器页面 →</button></div>`;}
const field=(label,name,value='',type='text',hint='',full=false)=>`<label class="field ${full?'full':''}"><span>${label}</span>${type==='textarea'?`<textarea name="${name}" rows="${name==='resume'?14:4}">${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${type==='password'?'autocomplete="new-password" placeholder="留空保留已保存的密钥"':''}>`}${hint?`<small>${hint}</small>`:''}</label>`;
const toggle=(label,name,value,desc)=>`<div class="switch-row"><div><strong>${label}</strong><p>${desc}</p></div><label class="switch"><input name="${name}" type="checkbox" ${value?'checked':''} aria-label="${label}"><i></i></label></div>`;
function settingsPage(){const s=state.settings;let fields='',title='',desc='';if(settingsTab==='search'){title='求职配置';desc='告诉助手你想找什么工作。修改后保存，下次任务开始时生效。';fields=`<div class="form-grid">${field('岗位关键词','keywords',s.keywords,'text','多个关键词使用逗号分隔，例如：AI 应用开发,后端开发')}${field('目标城市','cities',s.cities,'text','多个城市使用逗号分隔，例如：广州,深圳')}${field('最低月薪（元）','minSalary',s.minSalary,'number','0 表示不限；按页面薪资区间筛选')}${field('最高月薪（元）','maxSalary',s.maxSalary,'number','0 表示不限')}${field('排除关键词','excludedWords',s.excludedWords,'textarea','匹配岗位标题和描述，使用逗号分隔')}${field('屏蔽公司','excludedCompanies',s.excludedCompanies,'textarea','公司名称包含任一关键词即跳过')}${field('你的求职方向','direction',s.direction,'textarea','例如：优先正式研发岗位，希望使用 Python、FastAPI、RAG；不考虑外包。',true)}</div><p class="section-label">筛选与沟通</p>${toggle('启用 AI 岗位筛选','aiEnabled',s.aiEnabled,'结合简历与岗位描述给出匹配分数。需要先配置 AI 服务。')}${toggle('筛选通过后自动沟通','autoSend',s.autoSend,'开启后，任务会对 AI 判断合适的岗位点击“立即沟通”；关闭时仅入库供你确认。')}${toggle('按岗位要求生成专属招呼','personalizedGreeting',s.personalizedGreeting,'结合岗位要求与简历事实生成短招呼。同一会话已有本人开场就不再追加，包括 BOSS 固定招呼；没有开场时才发送专属文案。可在岗位详情预览；需保存配置。')}${toggle('专属招呼不可用时继续投递','greetingFallback',s.greetingFallback!==false,'默认开启，仅对自动任务生效：遇到已知可恢复的专属招呼问题时，继续发起平台沟通；不保证 BOSS 默认消息送达。无法核对 HR 与岗位时不发专属文案；已有开场不追加，结果不明不补发。关闭后保持严格模式。手动发送不回退。')}<div class="form-grid" style="margin-top:20px">${field('最低匹配分数','minScore',s.minScore,'number','0–100，评分不是录用概率')}${field('每日沟通上限','dailyLimit',s.dailyLimit,'number','1–150，默认 20；按本地记录计数（含待核实），达到后任务会停止')}${field('每个岗位间隔（秒）','delaySeconds',s.delaySeconds,'number','最少 10 秒；默认 30 秒')}</div><div class="notice">支持城市：${esc(state.cities.join('、'))}。取消会停止当前任务；登录失效、验证、平台限制、浏览器断开或未知传输异常仍会暂停。单个岗位的可恢复问题会记录后跳过。</div>`;}
 else if(settingsTab==='ai'){title='AI 服务';desc='选择 API 服务，或在官网授权使用你的 ChatGPT 订阅额度。';fields=aiProviderUI.fields(s);}
 else if(settingsTab==='resume'){title='简历配置';desc='完整的经历和技能，有助于判断岗位是否适合你。';fields=`<div class="import-area" data-action="resume-upload">${icon('upload')}<p>导入 TXT / Markdown / PDF 简历</p><small>PDF 支持文字型文档；扫描件请先识别文字或直接粘贴。</small></div><input type="file" id="resume-file" accept=".txt,.md,.pdf" hidden><div class="form-grid" style="margin-top:20px">${field('简历正文','resume',s.resume,'textarea','请检查导入后的文字是否完整。保存后用于岗位匹配和回复草稿。',true)}</div>`;}
 else if(settingsTab==='reply'){title='回复设置';desc='定义回复风格与工作时段。自动回复针对求职浏览器当前打开的会话。';fields=`<div class="form-grid">${field('回复要求','replyPrompt',s.replyPrompt,'textarea','尽量写清薪资期望、到岗时间和不接受的条件。',true)}${field('开始时间（北京时间）','replyStart',s.replyStart,'number','0–23 点')}${field('结束时间（北京时间）','replyEnd',s.replyEnd,'number','1–24 点，结束时间应晚于开始时间')}</div><div class="notice">收到面试、薪资、到岗、身份信息或简历附件相关消息时，会生成草稿供你确认。自动回复不会替你发送附件简历。</div>`;}
 else {title='数据与备份';desc='岗位、配置和消息保存在应用目录中的 data 文件夹。';fields=`<div class="notice">完整备份：关闭本地服务后复制整个 data 文件夹。API Key 的本地加密密钥也在该文件夹中，请妥善保管。</div><div class="inline-actions">${btn('导出岗位与消息','export','primary','download')}${btn('导入岗位 JSON','import','','upload')}</div><p class="section-label">体验数据</p><div class="inline-actions" style="margin-top:12px">${btn('添加示例岗位','demo','','spark')}${btn('清除示例岗位','clear-demo','','trash')}</div><p class="section-label">浏览器</p><div class="inline-actions" style="margin-top:12px">${btn('打开求职浏览器','open-browser','','globe')}${btn('关闭求职浏览器','close-browser','','close')}</div>`;}
 return heading('配置中心','按照你的节奏，设置适合自己的求职助手。')+`<div class="settings-layout"><aside class="panel settings-nav">${[['search','求职配置','search'],['ai','AI 服务','spark'],['resume','简历配置','file'],['reply','回复设置','message'],['data','数据与备份','inbox']].map(([id,label,i])=>`<button data-action="settings-tab" data-tab="${id}" class="${id===settingsTab?'active':''}">${icon(i)}${label}</button>`).join('')}</aside><section class="panel settings-panel"><h2>${title}</h2><p>${desc}</p><form id="settings-form">${fields}${settingsTab!=='data'?`<div class="form-actions">${btn('保存配置','save-settings','primary','check','type="button"')}<span class="save-note">配置保存在本机</span></div>`:''}</form></section></div>`;
}
function messagesPage(){const contacts=[...new Set(messages.map(m=>m.contact))];if(!contact||!contacts.includes(contact))contact=contacts[0]||'';const conv=messages.filter(m=>m.contact===contact);return heading('消息','集中查看对话，生成回复草稿，保留每一次沟通。',`<div class="inline-actions">${btn('粘贴对话','add-message','','plus')}${btn('同步当前会话','sync-chat','primary','refresh')}</div>`)+`<section class="panel messages-layout"><aside class="contacts">${contacts.length?contacts.map(c=>{const last=messages.filter(m=>m.contact===c).at(-1);return `<div class="contact ${c===contact?'active':''}" data-action="select-contact" data-contact="${esc(c)}"><span class="avatar">${esc(c.slice(0,1))}</span><div><strong>${esc(c)}</strong><p>${esc(last.text)}</p></div></div>`;}).join(''):empty('暂无会话','同步浏览器当前会话，或粘贴 HR 的消息。','message')}</aside><div class="chat-main">${contact?`<div class="chat-header"><strong>${esc(contact)}</strong>${pill('本地记录','blue')}</div><div class="chat-body">${conv.map(m=>`<div class="bubble-row ${m.role==='assistant'?'me':''}"><div class="bubble">${esc(m.text)}</div><small>${date(m.time)} ${pill(m.status,color(m.status))}${m.role==='assistant'&&m.status==='已发送'?pill(m.automatic===true?'自动发送':m.automatic===false?'人工确认':'发送方式未知'):''}${m.role==='assistant'?`<button class="text-btn" data-action="copy-message" data-id="${m.id}">复制</button>${m.status==='草稿'?`<button class="text-btn" data-action="edit-draft" data-id="${m.id}">编辑</button><button class="text-btn" data-action="send-message" data-id="${m.id}">发送到当前会话</button>`:''}`:''}</small></div>`).join('')}</div><div class="chat-compose">${btn('生成 AI 回复草稿','draft-reply','primary','spark')}${btn('粘贴新消息','add-message','','plus')}<span class="count-label">草稿可以编辑后再发送</span></div>`:empty('让沟通更从容','AI 会结合你的简历和对话内容起草回复。所有草稿都可以先查看和修改。','message')}</div></section><div class="notice">同步读取求职浏览器中当前选中的会话；历史会话需逐个打开同步。页面结构变化时，可粘贴对话继续使用本地草稿功能。</div>`;}
function analyticsPage(){const s=state.stats;const count=status=>jobs.filter(j=>j.status===status).length,max=Math.max(1,s.jobs),companies={};for(const j of jobs)if(j.company)companies[j.company]=(companies[j.company]||0)+1;return heading('求职分析','从真实记录中看见进展，找到下一步的方向。',`<div class="inline-actions">${btn('打印 / 保存 PDF','print','','print')}${btn('生成 AI 复盘','report','primary','spark')}</div>`)+`<div class="chart-grid"><section class="panel panel-body"><div class="panel-title"><h2>求职进展</h2><small>基于本地记录</small></div>${[['收集岗位',s.jobs],['匹配合适',count('合适')+s.sent],['已沟通',s.sent],['获得面试',s.interviews]].map(([label,n])=>`<div class="metric-row"><span>${label}</span><div class="bar"><b style="width:${n/max*100}%"></b></div><strong>${n}</strong></div>`).join('')}<p class="panel-desc" style="margin:0">面试状态需要你在岗位详情里手动标记。</p></section><section class="panel panel-body"><div class="panel-title"><h2>岗位分布</h2><small>公司 · 前五名</small></div>${Object.keys(companies).length?Object.entries(companies).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([c,n])=>`<div class="metric-row" style="grid-template-columns:130px 1fr 20px"><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(c)}</span><div class="bar"><b style="width:${n/max*100}%"></b></div><strong>${n}</strong></div>`).join(''):empty('数据还在积累','收集一些岗位后，这里会展示公司分布。','chart')}</section></div><section class="panel panel-body"><div class="panel-title"><h2>复盘记录</h2><small>生成时的数据快照</small></div>${reports.length?reports.map(r=>`<article class="report-card"><time>${date(r.time)} · ${r.stats.jobs} 个岗位 · ${r.stats.sent} 次沟通</time>${r.strategy?`<p class="panel-desc">策略：${esc(r.strategy)}</p>`:''}<div class="report-content">${esc(r.text)}</div></article>`).join(''):empty('记录你的第一次复盘','积累岗位和沟通数据后，AI 可以结合你的求职策略提出下一步建议。','chart')}</section>`;}
function draw(){nav();$('#app').innerHTML=page==='dashboard'?dashboard():page==='jobs'?jobsPage():page==='settings'?settingsPage():page==='messages'?messagesPage():analyticsPage();}
async function navigate(){try{await settingsSaver.flush();}catch(e){toast('配置未保存：'+e.message,true);return;}page=location.hash.slice(1)||'dashboard';if(!navs.some(n=>n[0]===page))page='dashboard';try{if(page==='jobs'||page==='analytics')jobs=await api('jobs');if(page==='messages')messages=await api('messages');if(page==='analytics')reports=await api('reports');await refresh();}catch(e){toast(e.message,true);}}
function formValues(form){const v={};for(const input of form.querySelectorAll('[name]')){v[input.name]=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value;}if(v.apiKey==='')delete v.apiKey;return v;}
function jobDialog(id){const j=jobs.find(j=>j.id===id);if(!j)return;modal(esc(j.title),`<div class="detail-meta">${pill(j.company||'未填写公司')}${pill(j.salary||'面议','orange')}${pill(j.city||'城市未填写')}${pill(j.status,color(j.status))}</div>${j.reason?`<div class="notice">${esc(j.reason)}</div>`:''}<div class="detail-description">${esc(j.description||'暂无岗位描述，可编辑补充或读取浏览器详情。')}</div><div class="section-label">沟通状态</div><select class="control" id="stage-select" data-id="${esc(id)}" style="margin-top:10px">${['未标记','有面试','已面试','面试通过','面试不通过','HR 已拒绝','AI 已婉拒'].map(x=>`<option ${j.stage===x?'selected':''}>${x}</option>`).join('')}</select>${j.url&&/^https:\/\/www\.zhipin\.com\//.test(j.url)?`<p><a class="text-btn" href="${esc(j.url)}" target="_blank" rel="noopener">查看原始岗位 ${icon('external')}</a></p>`:''}`,btn('编辑','edit-job','','file',`data-id="${esc(id)}"`)+btn('读取详情','read-detail','','refresh',`data-id="${esc(id)}"`)+btn('AI 分析','analyze-one','soft','spark',`data-id="${esc(id)}"`)+btn('确认沟通','send-job','primary','send',`data-id="${esc(id)}"`));}
function editJob(id){const j=jobs.find(j=>j.id===id)||{};modal(j.id?'编辑岗位':'添加岗位',`<form id="job-form"><div class="form-grid">${field('岗位名称','title',j.title)}${field('公司名称','company',j.company)}${field('薪资','salary',j.salary,'text','例如：15-25K')}${field('城市','city',j.city)}${field('岗位链接（可选）','url',j.url,'text','BOSS 直聘岗位详情链接',true)}${field('岗位描述','description',j.description,'textarea','粘贴完整的岗位职责和要求，AI 匹配会更准确。',true)}</div></form>`,btn('取消','close-modal')+btn('保存岗位','modal-submit','primary','check'));modalHandler=async()=>{await api('jobs/save',{...j,...formValues($('#job-form')),source:j.source||'手动添加'});closeModal();jobs=await api('jobs');draw();toast('岗位已保存');};}
const actions={
 'go-settings':()=>{location.hash='settings';},
 'go-jobs':()=>{location.hash='jobs';},
 'settings-tab':async el=>{await settingsSaver.flush();settingsTab=el.dataset.tab;draw();},
 'save-settings':async()=>{const values=formValues($('#settings-form'));if(values.autoSend&&!state.settings.autoSend&&!await confirmAction('启用自动沟通','开启后，点击工作台“开始”会对 AI 筛选通过的真实岗位执行沟通。请确认求职条件与简历已检查。','启用'))return;await api('settings',values);await refresh();toast('配置已保存');},
 'ai-test':async()=>{const r=await api('ai/test',formValues($('#settings-form')));toast('模型响应：'+r.message);},
 'ai-models':async()=>{const list=await api('ai/models',formValues($('#settings-form')));$('#model-list').innerHTML=`<label class="field" style="margin-bottom:16px"><span>可用模型</span><select id="model-choice"><option value="">选择模型</option>${list.map(n=>`<option>${esc(n)}</option>`).join('')}</select></label>`;toast('已获取 '+list.length+' 个模型');},
 'clear-key':async()=>{if(!await confirmAction('清除 API Key','清除本地保存的密钥，之后需重新填写。'))return;await api('settings',{apiKey:''});await refresh();toast('密钥已清除');},
 'open-browser':async()=>{await api('browser/open',{});await refresh(page==='dashboard');toast('浏览器已打开，请手动完成登录');},
 'close-browser':async()=>{await api('browser/close',{});await refresh();},
 'collect':async()=>{const r=await api('browser/collect',{});jobs=await api('jobs');await refresh();location.hash='jobs';toast(`已保存：新增 ${r.added} 个岗位，重复 ${r.duplicate} 个`);},
 'start-task':async()=>{if(state.settings.autoSend&&!await confirmAction('开始真实沟通任务','此任务会根据已保存的求职条件筛选岗位，并自动点击“立即沟通”。请确认浏览器登录的是你要使用的账号。','开始任务'))return;await api('task/start',{});await refresh();},
 'stop-task':async()=>{await api('task/stop',{});await refresh();},
 'start-reply':async()=>{if(!await confirmAction('开启当前会话自动回复','将每 30 秒检查浏览器当前会话，并在设定时段发送 AI 回复。涉及面试、薪资和附件等内容会保留为草稿。','开启'))return;await api('reply/start',{});await refresh();},
 'stop-reply':async()=>{await api('reply/stop',{});await refresh();},
 'clear-logs':async()=>{await api('logs/clear',{});await refresh();},
 'filter':el=>{jobFilter=el.dataset.filter;selected.clear();draw();},
 'add-job':()=>editJob(), 'edit-job':el=>editJob(el.dataset.id), 'job-detail':el=>jobDialog(el.dataset.id),
 'analyze-one':async el=>{const r=await api('jobs/analyze',{ids:[el.dataset.id]});if(r[0]?.error)throw Error(r[0].error);jobs=await api('jobs');if($('#modal').open)jobDialog(el.dataset.id);else draw();toast('分析已完成');},
 'analyze-selected':async()=>{if(!selected.size)throw Error('请先勾选岗位');const r=await api('jobs/analyze',{ids:[...selected]});jobs=await api('jobs');draw();toast('完成 '+r.filter(j=>!j.error).length+' 个，失败 '+r.filter(j=>j.error).length+' 个',r.some(j=>j.error));},
 'delete-selected':async()=>{if(!selected.size)throw Error('请先勾选岗位');if(!await confirmAction('删除选中岗位',`将删除 ${selected.size} 个本地岗位记录。历史投递防重复记录仍会保留。`,'删除'))return;await api('jobs/delete',{ids:[...selected]});selected.clear();jobs=await api('jobs');draw();},
 'read-detail':async el=>{await api('browser/detail',{id:el.dataset.id});jobs=await api('jobs');jobDialog(el.dataset.id);toast('岗位详情已更新');},
 'send-job':async el=>{const id=el.dataset.id;if(!await confirmAction('确认向此岗位发起沟通','将在 BOSS 直聘打开岗位并点击“立即沟通”。这会产生真实的沟通记录。','确认沟通'))return;const r=await api('jobs/send',{id});jobs=await api('jobs');draw();toast(r.reason,!r.verified);},
 'export':async()=>{download('a-border-job-backup-'+new Date().toISOString().slice(0,10)+'.json',await api('export'));toast('导出文件已生成，不含 API Key');},
 'import':()=>$('#import-file').click(),
 'demo':async()=>{await api('demo',{});jobs=await api('jobs');await refresh();toast('已添加 3 个示例岗位');},
 'clear-demo':async()=>{await api('demo/clear',{});jobs=await api('jobs');await refresh();toast('示例岗位已清除');},
 'resume-upload':()=>$('#resume-file').click(),
 'select-contact':el=>{contact=el.dataset.contact;draw();},
 'add-message':()=>{const selectedConversation=currentConversation();modal('添加收到的消息',`<form id="message-form"><div class="form-grid">${field('联系人 / 公司','contact',contact,'text','例如：王 HR · 星河科技',true)}${field('收到的消息','text','','textarea','粘贴 HR 发来的内容',true)}</div></form>`,btn('取消','close-modal')+btn('保存消息','modal-submit','primary'));modalHandler=async()=>{const b=formValues($('#message-form'));if(selectedConversation&&b.contact.trim()===selectedConversation.contact)b.conversationId=selectedConversation.id;const saved=await api('messages/add',b);conversationId=saved.conversationId;conversationFilter='全部';conversationQuery='';contact=b.contact;messages=await api('messages');await refresh(false);closeModal();draw();toast('消息已保存');};},
 'sync-chat':async()=>{const r=await api('messages/sync',{});contact=r.contact;messages=await api('messages');draw();toast('当前会话已同步');},
 'draft-reply':async()=>{await api('messages/draft',{contact});messages=await api('messages');draw();toast('回复草稿已生成');},
 'copy-message':async el=>{const m=messages.find(m=>m.id===Number(el.dataset.id));await navigator.clipboard.writeText(m.text);toast('已复制');},
 'edit-draft':el=>{const m=messages.find(m=>m.id===Number(el.dataset.id));modal('编辑回复草稿',`<form id="draft-form">${field('回复内容','text',m.text,'textarea')}</form>`,btn('取消','close-modal')+btn('保存','modal-submit','primary'));modalHandler=async()=>{await api('messages/save',{id:m.id,...formValues($('#draft-form'))});closeModal();messages=await api('messages');draw();};},
 'send-message':async el=>{const id=Number(el.dataset.id);if(!await confirmAction('发送这条回复','将发送到求职浏览器中的对应会话，请确认内容准确。','发送'))return;const r=await api('messages/send',{id});messages=await api('messages');draw();toast(r.verified?'消息已发送':'已尝试发送，请到浏览器核对',!r.verified);},
 'report':()=>{modal('生成求职复盘',`<form id="report-form">${field('本轮求职策略（可选）','strategy','','textarea','例如：本周重点投递广州的 AI 应用开发岗位，希望找到 20K 以上的正式岗位。')}</form><p class="notice">会把岗位摘要和统计发送到你配置的 AI 服务，生成一份保留数据快照的报告。</p>`,btn('取消','close-modal')+btn('生成复盘','modal-submit','primary','spark'));modalHandler=async()=>{await api('report',formValues($('#report-form')));closeModal();reports=await api('reports');draw();toast('复盘报告已保存');};},
 'print':()=>window.print(),
 'close-modal':()=>closeModal(),
 'confirm':()=>{const resolve=confirmResolver;confirmResolver=null;$('#modal').close();resolve?.(true);},
 'modal-submit':async()=>{if(modalHandler)await modalHandler();}
};
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();const action=actions[el.dataset.action];if(!action)return;const original=el.innerHTML;el.disabled=true;try{const result=action(el);if(result instanceof Promise){if(!['confirm','close-modal'].includes(el.dataset.action))el.innerHTML='<span class="spinner"></span> 处理中';await result;}}catch(err){toast(err.message,true);}finally{if(el.isConnected){el.disabled=false;el.innerHTML=original;}}});
document.addEventListener('submit',e=>e.preventDefault());
document.addEventListener('input',e=>{if(e.target.id==='job-search'){query=e.target.value;jobListUI.resetPage();$('#job-table').innerHTML=jobRows();jobListUI.updateSelection();}});
document.addEventListener('change',async e=>{try{const el=e.target;if(el.dataset.select){el.checked?selected.add(el.dataset.select):selected.delete(el.dataset.select);}if(el.id==='select-all'){$$('[data-select]').forEach(x=>{x.checked=el.checked;el.checked?selected.add(x.dataset.select):selected.delete(x.dataset.select);});}if(el.id==='model-choice'&&el.value)$('[name=aiModel]').value=el.value;if(el.id==='stage-select'){const j=jobs.find(j=>j.id===el.dataset.id);await api('jobs/save',{...j,stage:el.value});jobs=await api('jobs');toast('沟通状态已更新');}if(el.id==='resume-file'){const f=el.files[0];if(!f)return;if(f.size>8_000_000)throw Error('简历文件请小于 8 MB');if(f.name.toLowerCase().endsWith('.pdf')){const result=await api('resume/pdf',{base64:await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(f);})});$('[name=resume]').value=result.text;toast('PDF 文字已提取，请检查后保存');}else{$('[name=resume]').value=await f.text();toast('简历已读取，请保存配置');}}}catch(err){toast(err.message,true);}});
$('#import-file').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;const r=await api('import',JSON.parse(await f.text()));jobs=await api('jobs');await refresh();toast(`已导入 ${r.count} 个岗位`);}catch(e){toast(e.message,true);}finally{e.target.value='';}});
$('#help').addEventListener('click',()=>modal('开始使用',`<div class="detail-description">1. 在「配置中心 → 求职配置」填写关键词、城市和筛选条件。\n\n2. 在「AI 服务」填写接口、模型和 API Key，测试连接后保存。\n\n3. 在「简历配置」粘贴或导入简历，检查内容后保存。\n\n4. 回到工作台，打开求职浏览器，并在新开的 Chrome 窗口手动登录 BOSS 直聘。\n\n5. 可以先搜索岗位并点击“读取当前页”，也可以开启自动筛选。默认仅筛选，不自动沟通。\n\n6. 岗位详情里可确认沟通、标记面试状态；消息页可同步当前会话并生成 AI 草稿。\n\n安装目录：你解压程序的文件夹\n数据目录：安装目录下的 data 文件夹\n\n这是依据公开功能独立实现的本地版本。网页适配需要随 BOSS 直聘页面变化维护。企业查询、历史同步、附件处理与分析报告已提供；真实网站适配需要随页面变化维护。模拟环境使用虚构数据，不联系真实 HR。</div>`,btn('知道了','close-modal','primary')));
// Extended workflows: UI uses the same APIs in production and isolated simulation.
const originalSettingsPage=settingsPage,originalDashboard=dashboard,originalJobDialog=jobDialog;
let conversationId='',conversationQuery='',conversationFilter='全部',conversationLimit=50,conversationSelected=new Set();
const choice=(label,name,value,options)=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;
const pdfLink=(kind,id,label='下载 PDF')=>`<a class="btn" href="/api/${kind}/pdf?id=${encodeURIComponent(id)}" download>${icon('download')}${label}</a>`;
function simulationPanel(){return state.simulation?`<section class="simulation-banner"><div><strong>模拟演练环境</strong><p>岗位、企业、简历和 HR 均为虚构；使用独立数据目录，操作不会发给真实 HR。</p></div>${btn(state.audit?.running?'演练进行中':'运行完整演练','run-simulation','primary','play',state.audit?.running?'disabled':'')}</section>${state.audit?.steps?.length?`<details class="panel audit-list" ${state.audit.running?'open':''}><summary>演练结果：${state.audit.steps.filter(s=>s.status==='通过').length} / ${state.audit.steps.length} 项通过（展开查看）</summary>${state.audit.steps.map((s,i)=>`<div><span>${i+1}. ${esc(s.name)}</span>${pill(s.status,s.status==='通过'?'green':s.status==='失败'?'red':'blue')}${s.error?`<small>${esc(s.error)}</small>`:''}</div>`).join('')}</details>`:''}`:'';}
dashboard=function(){return originalDashboard().replaceAll('当前会话运行中','全部会话巡检中').replaceAll('开启当前会话自动回复','开启自动回复')+`<div class="setup-note">${icon('message')}<span>历史同步：${esc(state.syncTask.phase)}，本轮 ${state.syncTask.processed} 个会话 / ${state.syncTask.messages} 条新消息。</span><button data-action="${state.syncTask.running?'stop-history':'sync-history'}">${state.syncTask.running?'停止同步':'同步历史会话'} →</button></div>${!state.simulation?'<div class="notice">模拟操作：双击安装目录中的「模拟演练.vbs」，在独立环境体验完整流程。</div>':''}`;};
settingsPage=function(){const s=state.settings;let html=originalSettingsPage(),extra='';
 if(settingsTab==='search')extra=`<p class="section-label">完整筛选条件</p><div class="form-grid">${choice('求职类型','jobType',s.jobType,['不限','全职','兼职','实习'])}${choice('最低 HR 活跃度','minActivity',s.minActivity,['当前在线','今日活跃','3日内活跃','本周活跃','2周内活跃','本月活跃'])}${field('工作经验','experiences',s.experiences,'text','例如：经验不限,1-3年,3-5年')}${field('学历','educations',s.educations,'text','例如：大专,本科；留空不限')}${field('融资阶段','financingStages',s.financingStages,'text','例如：不需要融资,A轮,上市公司')}${field('企业规模','companySizes',s.companySizes,'text','例如：20-99人,100-499人')}${field('行业','industries',s.industries,'text','多个值用逗号分隔；缺失字段不会误判')}${field('职位名包含','titleIncludes',s.titleIncludes,'text','任意一个匹配即通过，逗号分隔')}${field('职位名排除','titleExcludes',s.titleExcludes)}${field('仅考虑这些公司','includedCompanies',s.includedCompanies)}</div>${toggle('筛选 HR 活跃度','activityEnabled',s.activityEnabled,'在岗位详情读取，未提供活跃度时放行。')}${toggle('简历技术匹配','resumeMatch',s.resumeMatch,'与 AI 岗位方向筛选独立，可分别开启。')}${toggle('按匹配分数筛选','scoreFilter',s.scoreFilter,'只在简历匹配开启时应用最低分。')}<p class="section-label">投递节奏</p><div class="form-grid">${choice('节奏预设','paceMode',s.paceMode,[['slow','慢速'],['normal','标准'],['fast','快速'],['custom','自定义']])}${field('每批岗位数量','restEvery',s.restEvery,'number','0 表示不加批次休息；自定义模式生效')}${field('岗位停顿下限（秒）','delayMin',s.delayMin,'number')}${field('岗位停顿上限（秒）','delayMax',s.delayMax,'number')}${field('翻页停顿下限（秒）','pageMin',s.pageMin,'number')}${field('翻页停顿上限（秒）','pageMax',s.pageMax,'number')}${field('批次休息下限（秒）','restMin',s.restMin,'number')}${field('批次休息上限（秒）','restMax',s.restMax,'number')}</div><div class="notice">标准节奏：每岗 3–8 秒，翻页 2–5 秒，每 15 岗休息 30–60 秒。AI 方向、简历匹配与基础筛选独立生效。</div>`;
 if(settingsTab==='reply')extra=`<p class="section-label">多会话与附件</p><div class="form-grid">${choice('回复范围','replyScope',s.replyScope,[['all','全部可读取会话'],['current','当前会话']])}${field('每批回复数量','replyRestEvery',s.replyRestEvery,'number')}${field('回复等待下限（秒）','replyDelayMin',s.replyDelayMin,'number')}${field('回复等待上限（秒）','replyDelayMax',s.replyDelayMax,'number')}${field('批次休息下限（秒）','replyRestMin',s.replyRestMin,'number')}${field('批次休息上限（秒）','replyRestMax',s.replyRestMax,'number')}</div>${toggle('自动处理附件简历请求','autoAttachment',s.autoAttachment,'HR 索要简历时操作已上传到 BOSS 的附件；需保存后生效。状态不明时暂停。')}<div class="notice">面试时间、薪资、身份信息等消息生成草稿供你确认。HR 拒绝时停止回复；手动设置的面试结果不会被自动识别覆盖。</div>`;
 if(settingsTab==='data')extra=`<p class="section-label">版本与演练</p><div class="inline-actions">${btn('检查版本','check-version','','refresh')}${state.simulation?btn('完整模拟演练','run-simulation','primary','play'):''}</div><p class="panel-desc">本地复刻版 ${esc(state.version)}。原版更新只能供功能对照，不能直接覆盖本程序。完整数据备份含会话、企业查询和统计快照；不含 API Key 与浏览器登录状态。</p>`;
 if(settingsTab==='ai')extra=`<div class="notice">兼容服务示例：OpenAI（https://api.openai.com/v1）、通义千问（https://dashscope.aliyuncs.com/compatible-mode/v1）、Kimi（https://api.moonshot.cn/v1）、智谱（https://open.bigmodel.cn/api/paas/v4）。模型及可用地址以你的服务商账户为准。</div>`;
 html=html.replace('自动回复针对求职浏览器当前打开的会话。','可以巡检全部会话或仅处理当前会话。').replace('自动回复不会替你发送附件简历。','附件操作可在下方单独开启。').replace('最少 10 秒；默认 30 秒','兼容旧配置；实际停顿使用下方节奏设置。').replace('结合简历与岗位描述给出匹配分数。需要先配置 AI 服务。','按求职方向判断岗位；简历匹配可在下方独立开启。');
 return html.includes('<div class="form-actions">')?html.replace('<div class="form-actions">',extra+'<div class="form-actions">'):html.replace('</form>',extra+'</form>');
};
jobRows=function(){const filtered=jobs.filter(j=>(jobFilter==='全部'||jobFilter==='已分析'&&j.analyzedAt||jobFilter==='高匹配'&&j.score>=80||j.status===jobFilter)&&[j.title,j.company,j.city,j.description].join(' ').toLowerCase().includes(query.toLowerCase()));if(!filtered.length)return empty('暂无匹配岗位','更换筛选条件，或读取浏览器中的岗位。','briefcase',btn('添加岗位','add-job','primary','plus'));return `<div class="table-wrap"><table><thead><tr><th><input type="checkbox" id="select-all" aria-label="选择全部筛选结果"></th><th>岗位 / 公司</th><th>薪资 / 活跃度</th><th>匹配分</th><th>筛选结果 / 理由</th><th>沟通状态</th><th>操作</th></tr></thead><tbody>${filtered.map(j=>{const c=state.companies.find(c=>c.name===j.company);return `<tr><td><input type="checkbox" data-select="${esc(j.id)}" ${selected.has(j.id)?'checked':''} aria-label="选择 ${esc(j.title)}"></td><td><button class="text-btn job-title" data-action="job-detail" data-id="${esc(j.id)}">${esc(j.title)}</button><span class="sub">${esc(j.company)} · ${esc(j.city||'城市未知')}</span>${c?pill(c.risk,c.risk==='高风险'?'red':''):''}${j.simulation?pill('虚构','orange'):''}${j.listKind==='首页推荐'?pill('首页推荐'):''}</td><td><b class="salary">${esc(j.salary||'面议')}</b><span class="sub">${esc(j.hrActivity||'活跃度未知')}</span></td><td>${j.score??'—'}</td><td>${pill(j.status,color(j.status))}<span class="sub reason" title="${esc(j.reason)}">${esc(j.reason||'待分析')}</span></td><td>${pill(j.stage||'未标记',color(j.stage))}</td><td><div class="actions"><button class="text-btn" data-action="company-query" data-id="${esc(j.id)}">企业查询</button><button class="text-btn" data-action="job-detail" data-id="${esc(j.id)}">详情</button></div></td></tr>`;}).join('')}</tbody></table></div>`;};
jobsPage=function(){return heading('岗位管理',`共 ${jobs.length} 个岗位 · 已筛选的结果与理由均保存在本机。`,`<div class="inline-actions">${btn('导入','import','','upload')}${btn('导出选中','export-jobs','','download')}${btn('添加岗位','add-job','primary','plus')}</div>`)+`<div class="toolbar"><div class="search">${icon('search')}<input id="job-search" placeholder="搜索岗位、公司或城市" value="${esc(query)}" aria-label="搜索岗位"></div><div class="filter-tabs">${['全部','待分析','分析失败','合适','不合适','已沟通','已分析','高匹配'].map(f=>`<button class="${jobFilter===f?'active':''}" data-action="filter" data-filter="${f}">${f}</button>`).join('')}</div>${btn('批量分析','analyze-selected','soft','spark')}${btn('删除选中','delete-selected','','trash')}</div><section class="panel" id="job-table">${jobRows()}</section>`;};
jobDialog=function(id){originalJobDialog(id);const j=jobs.find(j=>j.id===id);if(!j)return;const footer=$('#modal .modal-footer');footer.insertAdjacentHTML('afterbegin',btn('企业查询','company-query','','search',`data-id="${esc(id)}"`));if(!j.description&&j.url&&!state.task.busy&&!state.syncTask.busy){$('#modal .detail-description').textContent='正在补充岗位详情…';api('browser/detail',{id}).then(async()=>{jobs=await api('jobs');if($('#modal').open&&$('#stage-select')?.dataset.id===id)jobDialog(id);}).catch(e=>{if($('#modal .detail-description'))$('#modal .detail-description').textContent=e.message;});}};
function currentConversation(){return state.conversations.find(c=>c.id===conversationId);}
function conversationRows(){return state.conversations.filter(c=>(conversationFilter==='全部'||(conversationFilter==='未面试'?!['有面试','已面试','面试通过','面试不通过'].includes(c.stage):c.stage===conversationFilter))&&[c.contact,c.company,c.jobTitle].join(' ').toLowerCase().includes(conversationQuery.toLowerCase()));}
function contactList(){const list=conversationRows();return list.slice(0,conversationLimit).map(c=>`<div class="contact ${c.id===conversationId?'active':''}"><input type="checkbox" data-conv-select="${esc(c.id)}" aria-label="选择会话 ${esc(c.contact)}" ${conversationSelected.has(c.id)?'checked':''}><button class="conversation-entry" data-action="select-conversation" data-id="${esc(c.id)}"><strong>${esc(c.contact)} ${pill(c.stage)}</strong><p>${esc(c.company||c.jobTitle||'本地会话')}</p><small>${esc(c.lastText||'')}</small></button></div>`).join('')+(list.length>conversationLimit?btn('加载更多会话','more-conversations','wide'):(!list.length?empty('暂无会话','先同步历史会话，或粘贴收到的消息。','message'):''));}
messagesPage=function(){if(!currentConversation())conversationId=state.conversations[0]?.id||'';const c=currentConversation();contact=c?.contact||'';const conv=c?messages.filter(m=>m.conversationId===c.id||!m.conversationId&&m.contact===c.contact).sort((a,b)=>(a.order??a.id)-(b.order??b.id)):[];return heading('消息',`共 ${state.conversations.length} 个会话 · ${esc(state.syncTask.phase)}`,`<div class="inline-actions">${btn('粘贴对话','add-message','','plus')}${btn(state.syncTask.running?'停止同步':'同步全部历史',state.syncTask.running?'stop-history':'sync-history','primary','refresh')}</div>`)+`<div class="toolbar"><input class="control" id="conversation-search" placeholder="搜索 HR、公司或岗位" value="${esc(conversationQuery)}"><select class="control" id="conversation-filter">${['全部','未面试',...state.stages.filter(x=>x!=='未标记')].map(x=>`<option ${x===conversationFilter?'selected':''}>${x}</option>`).join('')}</select>${btn('导出选中 / 全部','export-conversations','','download')}${btn('删除选中','delete-conversations','','trash')}${btn('同步当前','sync-chat','','refresh')}</div><section class="panel messages-layout"><aside class="contacts" id="conversation-list">${contactList()}</aside><div class="chat-main">${c?`<div class="chat-header"><div><strong>${esc(c.contact)}</strong><small class="sub">${esc(c.company||'')} · ${esc(c.jobTitle||'')}</small></div><select class="control" id="conversation-stage">${state.stages.map(s=>`<option ${c.stage===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="chat-body">${conv.map(m=>`<div class="bubble-row ${m.role==='assistant'?'me':''}"><div class="bubble">${esc(m.text)}</div><small>${date(m.time)} ${pill(m.status,color(m.status))}${m.role==='assistant'&&m.status==='已发送'?pill(m.automatic===true?'自动发送':m.automatic===false?'人工确认':'发送方式未知'):''}${m.role==='assistant'?`<button class="text-btn" data-action="copy-message" data-id="${m.id}">复制</button>${m.status==='草稿'?`<button class="text-btn" data-action="edit-draft" data-id="${m.id}">编辑</button><button class="text-btn" data-action="send-message" data-id="${m.id}">确认发送</button>`:''}`:''}</small></div>`).join('')}</div><div class="chat-compose">${btn('生成回复草稿','draft-reply','primary','spark')}${btn('发送附件简历','send-attachment','','file')}${c.jobId?btn('企业查询','company-query','','search',`data-id="${esc(c.jobId)}"`):''}${btn('删除此会话','delete-conversation','','trash')}</div>`:empty('会话保存在本机','历史同步会逐个读取，停止后可以继续。','message')}</div></section><div class="notice">面试时间和薪资等事项保留草稿供你确认；删除只影响本地，再次同步可能恢复记录。</div>`;};
const probability=(label,v)=>`<div class="probability"><span>${label}</span><strong>${(v.mean*100).toFixed(1)}%</strong><small>95% 可信区间 ${(v.low*100).toFixed(1)}%–${(v.high*100).toFixed(1)}%</small><p>${v.success} 次成功 / ${v.n} 个可观测样本 ${v.small?pill('样本较少','orange'):''}</p></div>`;
analyticsPage=function(){return heading('求职分析','先冻结统计，再按需生成 AI 解读。小样本可信区间可能很宽。',btn('创建统计快照','report','primary','chart'))+`<section class="report-list">${reports.length?reports.map(r=>`<article class="panel report-card"><div class="panel-title"><div><h2>${esc(r.title||'历史复盘')}</h2><small>${date(r.time)}</small></div><div class="inline-actions">${pdfLink('report',r.id)}${btn('AI 解读 / 重试','interpret-report','soft','spark',`data-id="${r.id}"`)}${btn('删除','delete-report','','trash',`data-id="${r.id}"`)}</div></div>${r.analysis?`<div class="probabilities">${probability('投递后 HR 回应率（估计）',r.analysis.delivery)}${probability('自动回复后 HR 再回应率（估计）',r.analysis.reply)}</div><div class="funnel">${[['已投递','sent'],['有聊天记录','observable'],['HR 已回应','replied'],['HR 提及简历','resume'],['面试状态','interview']].map(([label,k])=>`<div><strong>${r.analysis.funnel[k]}</strong><span>${label}</span></div>`).join('')}</div><p class="notice">${esc(r.analysis.method)}。${r.analysis.funnel.unobservable} 个投递没有聊天记录，未计入回应率分母。</p>${r.delta?`<p class="panel-desc">与上次快照相比：投递回应均值 ${r.delta.delivery.toFixed(1)} 个百分点；回复后回应均值 ${r.delta.reply.toFixed(1)} 个百分点。</p>`:''}<details><summary>分组统计：匹配度 / HR 活跃度 / 企业风险</summary>${Object.entries(r.analysis.groups).map(([key,groups])=>`<h3>${({score:'匹配度',activity:'HR 活跃度',risk:'企业风险'})[key]}</h3><table><thead><tr><th>分组</th><th>投递样本</th><th>投递回应均值</th><th>95% 可信区间</th><th>回复后回应</th></tr></thead><tbody>${groups.map(g=>`<tr><td>${esc(g.name)}</td><td>${g.delivery.success}/${g.delivery.n}</td><td>${(g.delivery.mean*100).toFixed(1)}%</td><td>${(g.delivery.low*100).toFixed(1)}%–${(g.delivery.high*100).toFixed(1)}%</td><td>${g.reply.success}/${g.reply.n}</td></tr>`).join('')}</tbody></table>`).join('')}</details>`:''}<p class="panel-desc">策略：${esc(r.strategy||'未填写')}</p><div class="report-content">${esc(r.text)}</div></article>`).join(''):empty('创建第一份统计快照','无需配置 AI Key。冻结后的统计不会被后续数据改变。','chart')}</section>`;};
function showCompany(c,jobId){modal(esc(c.name)+' · 企业查询',`<div class="detail-meta">${pill(c.risk,c.risk==='高风险'?'red':'blue')}${c.simulation?pill('虚构演练','orange'):''}<span>${date(c.updatedAt)}</span></div><dl class="company-facts">${[['企业全称','legalName'],['法定代表人','legalRepresentative'],['注册资本','capital'],['成立时间','founded'],['经营状态','status'],['行业','industry']].map(([label,k])=>`<div><dt>${label}</dt><dd>${esc(c[k]||'未获取')}</dd></div>`).join('')}</dl><p class="notice">${esc(c.assessment)}</p><h3>公开资料与线索</h3>${(c.sources||[]).map((s,i)=>`<p><a href="${/^https?:\/\//.test(s.url)?esc(s.url):'#'}" target="_blank" rel="noopener">[${i+1}] ${esc(s.title)}</a><small class="sub">${esc(s.snippet)}</small></p>`).join('')||'<p>暂无公开检索结果。</p>'}${(c.errors||[]).map(e=>`<p class="notice">${esc(e)}</p>`).join('')}`,pdfLink('company',c.id)+btn('重新查询','company-refresh','','refresh',`data-id="${esc(jobId)}"`)+btn('关闭','close-modal','primary'));}
Object.assign(actions,{
 'start-task':async()=>{if(!state.simulation&&state.settings.autoSend&&!await confirmAction('开始自动沟通',state.settings.personalizedGreeting?'会先检查岗位与简历证据。BOSS 可能自动发送固定开场；同一会话已有本人开场时，软件不会再追加专属招呼。核对 HR 与岗位、确认没有开场后才发送专属文案。'+(state.settings.greetingFallback!==false?' 已开启自动任务回退：可恢复的专属招呼问题不会阻止后续平台沟通，但不保证 BOSS 默认消息送达；取消、验证、账号限制和未知传输异常仍会停止。':' 未开启回退：专属招呼检查不通过时跳过该岗位，或本轮仅继续筛选。'):'会对符合已保存条件的真实岗位发起沟通，请确认求职方向与简历。','开始'))return;await api('task/start',{});await refresh();},
 'start-reply':async()=>{if(state.replyTask.busy&&!state.replyTask.running)throw Error('正在停止，请等待当前操作完成');if(!state.simulation&&!await confirmAction('开启自动回复','会按已保存的范围和时段巡检会话并发送回复；面试、薪资等事项保留草稿。','开启'))return;await api('reply/start',{});await refresh();},
 'save-settings':async()=>{const v=formValues($('#settings-form'));await settingsSaver.flush();if(!state.simulation&&(v.autoSend&&!state.settings.autoSend||v.autoAttachment&&!state.settings.autoAttachment)&&!await confirmAction('启用自动发送','任务运行时会按此设置向真实 HR 发起沟通或发送已上传的附件简历。','启用并保存'))return;await api('settings',v);await refresh();toast('配置已保存');},
 'run-simulation':async()=>{await api('simulation/run',{});await refresh();toast('完整演练已开始');},
 'sync-history':async()=>{await api('history/start',{});await refresh();toast('历史同步已开始，可停止后继续');},
 'stop-history':async()=>{await api('history/stop',{});await refresh();},
 'select-conversation':el=>{conversationId=el.dataset.id;draw();},
 'more-conversations':()=>{conversationLimit+=50;$('#conversation-list').innerHTML=contactList();},
 'draft-reply':async()=>{await api('messages/draft',{conversationId});messages=await api('messages');draw();toast('草稿已生成');},
 'sync-chat':async()=>{const c=await api('messages/sync',{});conversationId=c.id;messages=await api('messages');await refresh();},
 'send-attachment':async()=>{if(!state.simulation&&!await confirmAction('发送附件简历','将使用 BOSS 账户中已上传的附件，向当前选中的 HR 发出附件或请求。','发送'))return;const r=await api('messages/attachment',{conversationId});messages=await api('messages');await refresh();toast(r.reason,!r.verified);},
 'company-query':async el=>{const c=await api('company/query',{id:el.dataset.id});await refresh(false);showCompany(c,el.dataset.id);},
 'company-refresh':async el=>{const c=await api('company/query',{id:el.dataset.id,force:true});await refresh(false);showCompany(c,el.dataset.id);},
 'export-jobs':()=>{const list=selected.size?jobs.filter(j=>selected.has(j.id)):jobs;download('岗位记录.json',{format:'ghost-job-local',simulation:state.simulation,jobs:list});toast(`已导出 ${list.length} 个岗位`);},
 'export-conversations':()=>{const list=conversationSelected.size?state.conversations.filter(c=>conversationSelected.has(c.id)):state.conversations;const ids=new Set(list.map(c=>c.id));download('会话记录.json',{format:'ghost-job-local',simulation:state.simulation,jobs:[],conversations:list,messages:messages.filter(m=>ids.has(m.conversationId)||!m.conversationId&&list.some(c=>c.contact===m.contact))});toast(`已导出 ${list.length} 个会话`);},
 'delete-conversations':async()=>{if(!conversationSelected.size)throw Error('请先勾选会话');if(!await confirmAction('删除本地会话',`删除 ${conversationSelected.size} 个会话及消息；不会删除 BOSS 上的记录。`,'删除'))return;await api('conversations/delete',{ids:[...conversationSelected]});conversationSelected.clear();messages=await api('messages');await refresh();},
 'delete-conversation':async()=>{if(!await confirmAction('删除此会话','只删除本地会话及消息，再次同步可能恢复。','删除'))return;await api('conversations/delete',{ids:[conversationId]});messages=await api('messages');await refresh();},
 'report':()=>{modal('创建统计快照',`<form id="report-form">${field('本轮求职策略','strategy','','textarea','记录本轮求职条件，方便比较。',true)}</form><p class="notice">统计在本机计算；创建后可单独请求 AI 解读。</p>`,btn('取消','close-modal')+btn('创建快照','modal-submit','primary'));modalHandler=async()=>{await api('report',formValues($('#report-form')));closeModal();reports=await api('reports');draw();toast('统计快照已保存');};},
 'interpret-report':async el=>{await api('report/interpret',{id:el.dataset.id});reports=await api('reports');draw();toast('AI 解读已更新，统计快照未改变');},
 'delete-report':async el=>{if(!await confirmAction('删除统计快照','将删除这一份本地报告。','删除'))return;await api('report/delete',{id:el.dataset.id});reports=await api('reports');draw();},
 'check-version':async()=>{const r=await api('version/check',{});modal('版本信息',`<p>本地复刻版：${esc(r.version)}</p><p>对照仓库：${esc(r.reference)}</p>${r.release?`<p>最新发布：${esc(r.release.version)}</p><a class="btn" target="_blank" rel="noopener" href="${esc(r.release.url)}">查看发布页</a>`:''}<p class="notice">${esc(r.note||'模拟环境未访问外部服务。')}</p>`,btn('关闭','close-modal','primary'));}
});
const originalDraw=draw;
draw=function(){originalDraw();if(state.simulation)$('#app').insertAdjacentHTML('afterbegin',simulationPanel());};
const settingsSaver=createSettingsSaver({
 save:patch=>api('settings',patch),
 onSaved:async()=>{if(!state)return;await refresh(false);const note=$('.save-note');if(note)note.textContent='修改已自动保存';},
 onError:error=>{const note=$('.save-note');if(note)note.textContent='尚未保存，请重试';toast('配置未保存：'+error.message,true);}
});
document.addEventListener('change',async e=>{const el=e.target;try{
 if(el.dataset.convSelect){el.checked?conversationSelected.add(el.dataset.convSelect):conversationSelected.delete(el.dataset.convSelect);}
 if(el.id==='conversation-filter'){conversationFilter=el.value;conversationLimit=50;$('#conversation-list').innerHTML=contactList();}
 if(el.id==='conversation-stage'){await api('conversations/update',{id:conversationId,stage:el.value});await refresh();toast('会话状态已保存');}
 if(el.closest('#settings-form')&&el.name&&!['autoSend','autoAttachment','personalizedGreeting','apiKey'].includes(el.name)){
  settingsSaver.enqueue({[el.name]:el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value});
  const note=$('.save-note');if(note)note.textContent='正在保存修改…';
 }
 }catch(e){toast(e.message,true);}});
window.addEventListener('beforeunload',e=>{if(settingsSaver.dirty){e.preventDefault();e.returnValue='';}});
document.addEventListener('input',e=>{if(e.target.id==='conversation-search'){conversationQuery=e.target.value;conversationLimit=50;$('#conversation-list').innerHTML=contactList();}});
setInterval(async()=>{if((state?.syncTask?.busy||state?.audit?.running||state?.replyTask?.busy)&&!$('#modal').open){try{if(page==='messages')messages=await api('messages');if(page==='jobs')jobs=await api('jobs');if(page==='analytics')reports=await api('reports');await refresh(page!=='settings');}catch(e){toast(e.message,true);}}},2000);

function existingBrowserGuide(){
 modal('连接你已登录的 Chrome',`<p>连接后沿用这个 Chrome 中的 BOSS 登录状态。</p><ol><li>保留已经登录的 BOSS 标签页。</li><li>点击下方“打开 Chrome 连接设置”，开启“允许此浏览器实例的远程调试”。</li><li>回来点击“连接并选择 BOSS 页面”，在 Chrome 的连接弹窗中点击允许。</li></ol><p class="notice">设置地址：<code>chrome://inspect/#remote-debugging</code><br>连接期间 Chrome 会显示调试提示；点击“断开浏览器连接”可随时结束连接。</p><div class="notice"><strong>页面诊断</strong><p>${esc(browserDiagnosticsInstructions)}</p><p>仅生成当前页面的本机诊断，不发送 HR 消息，也不启动任务。</p></div><p id="browser-connect-status" role="status"></p>`,btn('打开 Chrome 连接设置','browser-setup','','settings')+btn('连接并选择 BOSS 页面','connect-existing-now','primary','globe')+btn('生成页面诊断','browser-diagnostics','soft','file',state.browser.connected?'':'disabled'));
}
async function connectExistingBrowser(targetId){
 const status=$('#browser-connect-status');if(status)status.textContent='正在连接，请到 Chrome 的弹窗中点击允许…';
 try{
  const result=await api('browser/connect',targetId?{targetId}:{});
  await refresh();
  if(result.needsSelection){
   const content=result.targets.length?`<p>请选择软件要使用的 BOSS 标签页：</p>${result.targets.map(t=>`<div class="notice"><strong>${esc(t.title||'BOSS 直聘')}</strong><p>${esc(t.url)}</p>${btn('使用这个页面','select-existing-target','primary','check',`data-id="${esc(t.id)}"`)}</div>`).join('')}`:'<p>连接已允许，但没有找到 BOSS 标签页。请在这个 Chrome 中打开已登录的 BOSS 页面，然后重试。</p>';
   modal('选择已登录的 BOSS 页面',content+'<p id="browser-connect-status" role="status"></p>',btn('重新读取标签页','connect-existing-now','soft','refresh'));return;
  }
  closeModal();toast('已连接你原有的 BOSS 页面，沿用原登录状态');
 }catch(error){if(status)status.textContent=error.message;throw error;}
}
Object.assign(actions,{
 'connect-existing':existingBrowserGuide,
 'browser-diagnostics':createBrowserDiagnosticsAction({api,modal,btn,esc,toast}),
 'browser-setup':async()=>{await api('browser/setup',{});toast('已打开 Chrome 连接设置，请开启远程调试后回来连接');},
 'connect-existing-now':()=>connectExistingBrowser(),
 'select-existing-target':el=>connectExistingBrowser(el.dataset.id),
 'use-dedicated-browser':async()=>{await api('browser/dedicated',{});await refresh();toast('已打开独立求职浏览器');},
 'open-browser':async()=>{if(!state.simulation&&state.browser.mode==='existing')return existingBrowserGuide();await api('browser/open',{});await refresh();toast('求职浏览器已打开');}
});
const dashboardBeforeBrowserConnection=dashboard;
dashboard=function(){
 let html=dashboardBeforeBrowserConnection();if(state.simulation)return html;
 const connected=state.browser.connected&&state.browser.mode==='existing';
 const controls=`<div class="notice"><strong>${connected?'已连接你的日常 Chrome':state.browser.mode==='existing'?'已选择日常 Chrome · 尚未连接':'浏览器连接'}</strong><p>${connected?esc(state.browser.title):'已有 BOSS 登录页面？点击下方按钮沿用原登录状态。'}</p>${btn(connected?'重新选择 BOSS 页面':'连接已登录 Chrome','connect-existing','primary','globe')}${connected?btn('断开浏览器连接','close-browser','','close'):''}</div>`;
 html=html.replace('<div class="run-state">',controls+'<div class="run-state">');
 html=html.replace('首次使用先打开求职浏览器，手动登录 BOSS 直聘。',state.browser.mode==='existing'?'请连接日常 Chrome 中已登录的 BOSS 页面。':'可连接已登录 Chrome，或使用独立求职浏览器。');
 html=html.replace('打开求职浏览器</button>','连接浏览器</button>');
 return html;
};
const settingsBeforeBrowserConnection=settingsPage;
settingsPage=function(){let html=settingsBeforeBrowserConnection();if(state.simulation||settingsTab!=='data')return html;return html.replace('<p class="section-label">浏览器</p>',`<p class="section-label">浏览器</p><div class="inline-actions">${btn('连接已登录 Chrome','connect-existing','primary','globe')}${btn('改用独立求职浏览器','use-dedicated-browser','','external')}</div>`).replace('关闭求职浏览器</button>',state.browser.mode==='existing'?'断开浏览器连接</button>':'关闭求职浏览器</button>');};

