function updateWorkspaceStatus(){
 if(!state)return;
 $('#page-label').textContent=navs.find(item=>item[0]===page)?.[1]||'工作台';
 const badge=$('#connection-status');
 badge.classList.toggle('offline',!state.browser.connected);
 badge.innerHTML=`<i class="dot"></i>${state.browser.connecting?'浏览器连接中':state.browser.connected?'浏览器已连接':'浏览器未连接'}`;
 document.body.dataset.page=page;
}
const drawWorkspace=draw;
draw=function(){
 const previousPage=document.body.dataset.page,scroll=$('.logs')?.scrollTop||0;
 const focused=document.activeElement,focusAction=page==='dashboard'&&focused?.dataset.action,focusFilter=focused?.dataset.filter;
 const searchFocus=['job-search','conversation-search'].includes(focused?.id)?{id:focused.id,start:focused.selectionStart,end:focused.selectionEnd}:null;
 const expandedPanels=['.advanced-settings','.more-menu'].filter(selector=>$(selector)?.open);
 drawWorkspace();if($('.logs'))$('.logs').scrollTop=scroll;updateWorkspaceStatus();if(page==='jobs')jobListUI.updateSelection();
 aiProviderUI.mount().catch(error=>toast(error.message,true));
 if(previousPage&&previousPage!==page)window.scrollTo(0,0);
 if(previousPage===page){
  expandedPanels.forEach(selector=>{if($(selector))$(selector).open=true;});
  if(searchFocus&&$('#'+searchFocus.id)){const input=$('#'+searchFocus.id);input.focus({preventScroll:true});input.setSelectionRange(searchFocus.start,searchFocus.end);}
 }
 if(focusAction)$$('[data-action]').find(el=>el.dataset.action===focusAction&&el.dataset.filter===focusFilter)?.focus({preventScroll:true});
};
document.addEventListener('change',e=>{
 if(page!=='jobs')return;
 if(e.target.id==='job-page-size'){
  jobListUI.changePageSize(e.target.value);$('#job-table').innerHTML=jobRows();
 }
 if(e.target.dataset.select||e.target.id==='select-all'||e.target.id==='job-page-size')jobListUI.updateSelection();
});
